#include <stdint.h>
#ifdef DEWY_PROFILE_GENERATE
#include <stdio.h>
#include <stdlib.h>
#include <gcov.h>
extern const struct gcov_info *__start_gcov_info[], *__stop_gcov_info[];
__attribute__((no_profile_instrument_function))
static void profile_write(const void *data, unsigned size, void *arg) {
  if (fwrite(data, 1, size, arg) != size) __builtin_trap();
}
__attribute__((no_profile_instrument_function))
static void profile_name(const char *name, void *arg) {
  __gcov_filename_to_gcfn(name, profile_write, arg);
}
__attribute__((no_profile_instrument_function))
static void *profile_allocate(unsigned size, void *arg) {
  (void)arg; void *result = malloc(size); if (!result) __builtin_trap(); return result;
}
#endif
__attribute__((no_profile_instrument_function))
void dewy_host_profile_dump(void) {
#ifdef DEWY_PROFILE_GENERATE
  FILE *stream = fopen(DEWY_PROFILE_STREAM, "wb");
  if (!stream) __builtin_trap();
  for (const struct gcov_info **p = __start_gcov_info; p != __stop_gcov_info; ++p)
    __gcov_info_to_gcda(*p, profile_name, profile_write, profile_allocate, stream);
  if (fclose(stream)) __builtin_trap();
#endif
}
